import numpy as np
from scipy.optimize import minimize

def objective(a):
    return -np.sum(a**2)

def constraint_sum_cubes(a):
    return np.sum(a**3)

def solve_for_n(n):
    # Initial guess: a mix of positive and negative values
    # a_i <= 2/sqrt(n)
    limit = 2 / np.sqrt(n)
    a0 = np.zeros(n)
    a0[0] = limit
    a0[1] = -limit

    bounds = [(-np.inf, limit) for _ in range(n)]
    cons = {'type': 'eq', 'fun': constraint_sum_cubes}

    res = minimize(objective, a0, method='SLSQP', bounds=bounds, constraints=cons)
    return -res.fun

for n in range(2, 11):
    print(f"n={n}, max_sum_sq={solve_for_n(n)}")

import numpy as np

def max_sum_sq_for_k(n, k):
    return (4/n) * (k + (n-k)**(1/3) * k**(2/3))

def find_max_for_n(n):
    return max(max_sum_sq_for_k(n, k) for k in range(1, n))

for n in range(2, 11):
    print(f"n={n}, max={find_max_for_n(n)}")

import numpy as np

def max_sum_sq_for_k(n, k):
